var e={"term.setting":`Mode code`,"term.settingDesc":`Pour coder avec Claude : un terminal sous la conversation (Ctrl+J, /terminal), ouvert dans les dépôts git de la session. Les changements de chaque réponse (diff, commit, push, PR) s'affichent même sans ce mode. Jamais pour les agents. Demande votre mot de passe pour l'activer.`,"term.enableTitle":`Activer le mode code`,"term.enableDesc":`Le mode code ajoute un terminal, qui lance n'importe quelle commande sur ce serveur avec ses droits. Tapez votre mot de passe pour confirmer.`,"term.password":`Mot de passe`,"term.badPassword":`Mot de passe incorrect`,"term.enable":`Activer`,"term.openFailed":`Le terminal ne s'est pas ouvert`,"term.tooMany":`4 terminaux sont ouverts : fermez-en un d'abord`,"term.close":`Fermer ce terminal`,"term.new":`Nouveau terminal`,"term.quote":`Envoyer la sélection à Claude`,"term.openCount":`{count} ouverts`,"term.openCount#one":`{count} ouvert`,"term.closeAll":`Tout fermer`,"term.hide":`Masquer le terminal`,"term.opening":`Ouverture…`,"term.ended":`[terminal terminé]`,"term.topicFolder":`Dossier du topic`};export{e as default};